import{_ as l}from"./chunks/rak产品管理.rz20lI6C.js";import{_ as s,o as r,c as i,a2 as n}from"./chunks/framework.BXzK3EA4.js";const a="/assets/%E5%8D%95%E5%87%BB%E4%BA%A7%E5%93%81%E6%9C%8D%E5%8A%A1%E5%90%8D%E7%A7%B0.BglQ8cZX.png",o="/assets/%E6%9C%8D%E5%8A%A1%E8%AF%B7%E6%B1%82%E5%8F%96%E6%B6%88.beC9CiP7.png",e="/assets/%E5%88%B0%E6%9C%9F%E4%B8%8D%E5%86%8D%E7%BB%AD%E8%AE%A2.CLkosuvX.png",p="/assets/%E4%BA%A7%E5%93%81%E5%8F%96%E6%B6%88%E5%AE%8C%E6%88%90.BtgPRZx6.png",g="/assets/%E7%8B%AC%E6%9C%8D%E7%A7%BB%E9%99%A4%E8%AF%B7%E6%B1%82.IfdQx3eD.png",f=JSON.parse('{"title":"产品取消和退订","description":"","frontmatter":{"title":"产品取消和退订"},"headers":[],"relativePath":"beginners-guide/manage-products/cancellation.md","filePath":"beginners-guide/manage-products/cancellation.md","lastUpdated":1788259091000}'),c={name:"beginners-guide/manage-products/cancellation.md"};function E(_,t,m,u,d,B){return r(),i("div",null,[...t[0]||(t[0]=[n('<p>产品取消与退订是用户在产品租用 / 托管服务周期内，主动终止服务协议、停止使用目标资源的操作行为，适用于物理服务器、裸机云、vps等各类租用场景。</p><hr><h3 id="产品取消" tabindex="-1">产品取消 <a class="header-anchor" href="#产品取消" aria-label="Permalink to &quot;产品取消&quot;">​</a></h3><p>RakSmart 产品取消包括到期用户不再续费和立即取消两种情况。</p><blockquote><p><strong>说明</strong></p><ul><li>生效规则：如选择的是 账单周期结束 后取消 ，则不会立即停止服务，而是在当前账单周期结束后终止服务。例如当前是 1 月订阅，申请取消后可持续使用到 1 月账单周期到期；</li><li>费用说明：提交取消后无法再对订单进行续费操作；</li><li>数据注意：请在提交取消申请前备份服务器内的所有数据，服务终止后数据会被清理，无法恢复。</li></ul></blockquote><ol><li><p>登录 <a href="https://billing.raksmart.com/whmcs/index.php?rp=/user/security" target="_blank" rel="noreferrer">RakSmart 控制台</a>。</p></li><li><p>在控制台左侧导航<strong>产品管理</strong>区域，单击需要取消服务的产品，进入<strong>我的产品与服务</strong>详情页面。</p><p><img src="'+l+'" alt="rak产品管理.png"></p></li><li><p>选择需要取消服务的服务器，单击<strong>产品/服务</strong>名称进入<strong>管理产品</strong>页面。 <img src="'+a+'" alt="单击产品服务名称.png"></p></li><li><p>单击<strong>请求取消</strong>，进入<strong>账户取消请求</strong>页面。 <img src="'+o+'" alt="服务请求取消.png"></p></li><li><p><strong>简要说明取消理由</strong>，选择<strong>取消类型</strong>，单击<strong>请求取消</strong>。 <img src="'+e+'" alt="到期不再续订.png"></p><ul><li>账单周期结束：指服务器到期用户不再续费，用户取消服务器后不产生退款。</li><li>立即：指立即终止服务器的使用，可能产生退款。退款规则的介绍可参考退款规则。</li></ul></li><li><p>单击<strong>请求取消</strong>，系统提示如下信息；单击<strong>返回</strong>可以回到管理产品页面。</p><p><img src="'+p+'" alt="产品取消完成.png"></p></li><li><p>若您需要继续使用产品或者撤销取消申请，单击<strong>移除请求</strong>。</p><p><img src="'+g+'" alt="独服移除请求.png"></p></li></ol><h3 id="退款规则" tabindex="-1">退款规则 <a class="header-anchor" href="#退款规则" aria-label="Permalink to &quot;退款规则&quot;">​</a></h3><ul><li><p>退款金额计算：按产品剩余使用期限折算退款金额。</p><ul><li>月付退款金额 =（支付金额÷30）x 退款天数(30天-已使用天数)- 手续费；</li><li>季付、半年付、年付套餐申请退款时，将按月付标准单价核算已使用时长的费用；</li><li>若套餐包含赠送的时长 / 资源，且申请退款时赠送部分未使用完毕，需按对应产品的月付标准单价补足赠送部分的差价，再核算剩余款项退款金额。</li></ul></li><li><p>退款到账：根据支付方式的不同退款方式主要分为以下两种</p><ul><li>非余额支付：您可选择该支付接口支持的退款方式（如原路退回），款项将按支付平台的处理周期到账。如遇节假日，到账时间可能顺延；</li><li>余额支付：退款将退回至您的账户余额，即时到账；不支持提现。</li></ul></li><li><p>数据保留：退订成功后，产品即刻回收且不可恢复。相关数据将被永久删除，无法恢复；</p></li><li><p>特殊说明：若退订产品为套餐类产品（含多个子资源），退款将按套餐整体剩余期限折算，不支持单独退订套餐内某一子资源。</p></li></ul>',8)])])}const b=s(c,[["render",E]]);export{f as __pageData,b as default};
